The following Node.js script polls a CKB node but has multiple bugs including a race condition, missing error handling, and a connection leak. Find and fix all issues.

```javascript
const http = require('http');

let requestId = 0;

async function rpcCall(method, params = []) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({
      id: ++requestId,
      jsonrpc: '2.0',
      method,
      params
    });

    const req = http.request({
      hostname: 'localhost',
      port: 8114,
      path: '/',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': body.length  // BUG 1: should use Buffer.byteLength
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        const parsed = JSON.parse(data);  // BUG 2: no try/catch, throws on invalid JSON
        resolve(parsed.result);
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function pollOnce() {
  const info = rpcCall('get_blockchain_info');  // BUG 3: missing await — info is a Promise
  const peers = await rpcCall('get_peers');

  const height = info.result?.tip_block_number;  // BUG 4: info is Promise, not result
  console.log(`Height: ${height}, Peers: ${peers.length}`);
}

function startPolling(intervalMs) {
  pollOnce();
  const timer = setInterval(() => {
    pollOnce();  // BUG 5: unhandled promise rejection if pollOnce throws
  }, intervalMs);
  return timer;
}

// Entry point
const timer = startPolling(10000);

process.on('SIGINT', () => {
  clearInterval(timer);
  console.log('Stopped');
  // BUG 6: no process.exit() — process hangs due to open http keep-alive
});
```

For each bug:
1. Identify the line and bug type (logic error, race condition, missing error handling, resource leak, etc.)
2. Explain the exact failure mode — what goes wrong and when
3. Show the fixed code for that section

Then provide the complete corrected script.
